type Quote = { id: string; enquiryId: string; customerId?: string; customerName: string; site: string; service: string; items: QuoteItem[]; taxRate: number; discount: number; status: QuoteStatus; createdAt: string; validUntil: string; assumptions: string; exclusions: string; approvedBy?: string; incomplete?: boolean };
